import itertools
from collections import Counter
from functools import lru_cache

UNIT = 800
DISCOUNTS = {0: 0, 1: 0, 2: 5, 3: 10, 4: 20, 5: 25}

def group_price(k):
    return k * UNIT * (100 - DISCOUNTS[k]) // 100

@lru_cache(maxsize=None)
def dp(counts):
    # counts is a sorted tuple descending
    if not any(counts):
        return 0
    res = float('inf')
    # Try forming a group of size k for k in 1..5
    # Any combination of k books that have count > 0
    # Because counts are indistinguishable titles with frequencies, choosing k titles
    # To avoid permutation explosion, choose k indices
    available = [i for i, c in enumerate(counts) if c > 0]
    for k in range(1, len(available) + 1):
        for combo in itertools.combinations(available, k):
            new_counts = list(counts)
            for idx in combo:
                new_counts[idx] -= 1
            new_counts.sort(reverse=True)
            res = min(res, group_price(k) + dp(tuple(new_counts)))
    return res

import book_store

# Test all frequency vectors where sum of counts <= 25 (up to 5 of each book)
mismatches = []
