import itertools
from functools import lru_cache
import book_store

UNIT = 800
DISCOUNTS = {0: 0, 1: 0, 2: 5, 3: 10, 4: 20, 5: 25}

def group_price(k):
    return int(k * UNIT * (100 - DISCOUNTS[k]) / 100)

@lru_cache(maxsize=None)
def dp(counts):
    if not any(counts):
        return 0
    res = 10**9
    available = [i for i, c in enumerate(counts) if c > 0]
    for k in range(1, len(available) + 1):
        for combo in itertools.combinations(available, k):
            new_counts = list(counts)
            for idx in combo:
                new_counts[idx] -= 1
            new_counts.sort(reverse=True)
            res = min(res, group_price(k) + dp(tuple(new_counts)))
    return res

mismatches = 0
total_checked = 0
for c1 in range(8):
    for c2 in range(c1 + 1):
        for c3 in range(c2 + 1):
            for c4 in range(c3 + 1):
                for c5 in range(c4 + 1):
                    counts = (c1, c2, c3, c4, c5)
                    basket = []
                    for idx, c in enumerate(counts):
                        basket.extend([idx + 1] * c)
                    actual = book_store.total(basket)
                    expected = dp(counts)
                    total_checked += 1
                    if actual != expected:
                        mismatches += 1

print('Total profiles checked:', total_checked)
print('Mismatches:', mismatches)
